WITH valid_employees AS (SELECT * FROM employees WHERE salary <= 124000 AND manager_id IS NULL), summary AS (SELECT CASE WHEN salary >= 132000 THEN 'high' WHEN salary >= 56000 THEN 'mid' ELSE 'low' END AS salary_bucket, CASE WHEN YEAR(hire_date) < 2024 THEN 'before_2024' WHEN YEAR(hire_date) = 2024 THEN '2024' ELSE 'after_2024' END AS hire_cohort, AVG(salary) AS avg_salary FROM valid_employees GROUP BY CASE WHEN salary >= 132000 THEN 'high' WHEN salary >= 56000 THEN 'mid' ELSE 'low' END, CASE WHEN YEAR(hire_date) < 2024 THEN 'before_2024' WHEN YEAR(hire_date) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT salary_bucket, hire_cohort, avg_salary FROM summary WHERE avg_salary > 63000
